                if src_ld <= 0:
                    continue
                best_di = None
                best_cand = None
                best_cost = None

                for di in order_dest:
                    if di == si:
                        continue
                    dest_rt = routes_list[di]
                    if route_load(dest_rt) + src_ld > cap:
                        continue
                    # choose best orientation for appending at the end of dest
                    cand1 = dest_rt + src_rt
                    cand2 = dest_rt + src_rt[::-1]
                    c1 = route_cost(cand1)
                    c2 = route_cost(cand2)
                    if best_cost is None or min(c1, c2) < best_cost:
                        if c1 <= c2:
                            best_cost = c1
                            best_di = di
                            best_cand = cand1
                        else:
                            best_cost = c2
                            best_di = di
                            best_cand = cand2

                if best_di is not None:
                    # remove source route, replace destination
                    routes_list[best_di] = best_cand
                    routes_list.pop(si)
                    changed = True
                    break

    # Final deterministic cleanup: ensure all customers are covered exactly once; if not, fallback to singleton routes.
    covered = []
    seen = set()
    for rt in routes_list:
        for v in rt:
            if v in seen:
                # duplicate found: fallback
                covered = []
                break
            seen.add(v)
            covered.append(v)
        if not covered:
            break
    if len(covered) != m or set(covered) != set(customers):
        # rebuild from scratch deterministically (still feasible when total demand <= cap * K hint is expected)
        routes_list = []
        cur = []
        cur_ld = 0
        for i in customers:
            dv = dem[i]
            if cur and cur_ld + dv > cap:
                routes_list.append(cur)
                cur = [i]
                cur_ld = dv
            else:
                cur.append(i)
                cur_ld += dv
        if cur:
            routes_list.append(cur)

        # cap the number of routes if necessary by further splitting; never merges could violate capacity.
        if len(routes_list) > K and K > 0:
            # keep first K routes, and push remaining customers as singleton routes after splitting sequentially
            kept = routes_list[:K]
            remaining = []
            for rt in routes_list[K:]:
                remaining += rt
            routes_list = kept
            for v in remaining:
                routes_list.append([v])

    return routes_list
